// The board drivers. Which chips and pins come from a BoardConfig at run time
// (board_config_types.h): today the build's kBoardConfig (board_config.h,
// generated by tools/boards.py from firmware/boards.json). Every driver is in
// every build, so a new board is a new profile; code goes here only for a
// display, touch or expander chip not driven yet.
//
// Displays: ILI9341, ST7789 and ST7796 over SPI (Arduino_GFX). Touch: CST816 and FT6336,
// which share one register layout (status at 0x02, the first point at 0x03-0x06).
// Expander: TCA9554 on the touch chip's I2C bus, for boards that put the panel's
// reset or a held pin on it.

#include <Arduino.h>
#include <Arduino_GFX_Library.h>
#include <Wire.h>
#include <esp_system.h>

#include "board_config.h"
#include "board_profile.h"
#include "touch_map.h"

extern const BoardProfile kBoard = BOARD_PROFILE_INIT;

// The board being driven.
static const BoardConfig &cfg = kBoardConfig;

// A profile's pin: GPIO n is n, expander pin n is 100 + n, none is -1.
constexpr int16_t kExio = 100;
static int8_t gpio_or_none(int16_t pin) { return pin >= 0 && pin < kExio ? pin : GFX_NOT_DEFINED; }
// The panel unturned: Arduino_GFX takes these and turns the picture itself.
static int16_t native_w() { return cfg.rotation & 1 ? kBoard.height : kBoard.width; }
static int16_t native_h() { return cfg.rotation & 1 ? kBoard.width : kBoard.height; }

// The SPI bus, in the profile's mode when it names one. Arduino_GFX's panel
// classes pick a mode themselves (ST7789 and ST7796: 3, ILI9341: 0), and the
// 3.5"'s ST7796 needs 0: with CS tied low it can't resync (boards.json).
class ProfileSPI : public Arduino_ESP32SPI {
 public:
  ProfileSPI(int8_t dc, int8_t cs, int8_t sck, int8_t mosi, int8_t miso, int8_t mode)
      : Arduino_ESP32SPI(dc, cs, sck, mosi, miso), mode_(mode) {}
  bool begin(int32_t speed, int8_t data_mode) override {
    return Arduino_ESP32SPI::begin(speed, mode_ >= 0 ? mode_ : data_mode);
  }

 private:
  int8_t mode_;
};

static Arduino_DataBus *bus;
static Arduino_TFT *panel;

static Arduino_TFT *make_panel() {
  const int8_t rst = gpio_or_none(cfg.lcd_rst);
  const int16_t *o = cfg.offsets;
  switch (cfg.panel) {
    case PanelDriver::ST7796:
      return new Arduino_ST7796(bus, rst, cfg.rotation, cfg.ips, native_w(), native_h(), o[0], o[1], o[2], o[3]);
    case PanelDriver::ILI9341:
      return new Arduino_ILI9341(bus, rst, cfg.rotation, cfg.ips, native_w(), native_h(), o[0], o[1], o[2], o[3]);
    case PanelDriver::ST7789:
    default:
      return new Arduino_ST7789(bus, rst, cfg.rotation, cfg.ips, native_w(), native_h(), o[0], o[1], o[2], o[3]);
  }
}

// TCA9554 registers: 0x01 the outputs, 0x03 the directions (1 = input). It
// powers up all inputs, pulled high.
static uint8_t exio_out = 0xFF, exio_dir = 0xFF;
static void exio_set(uint8_t reg, uint8_t value) {
  Wire.beginTransmission(cfg.expander_address);
  Wire.write(reg);
  Wire.write(value);
  Wire.endTransmission();
}

static void pin_write(int16_t pin, bool high) {
  if (pin < 0) return;
  if (pin >= kExio) {
    if (cfg.expander != ExpanderDriver::TCA9554) return;  // boards.py refuses expander pins without one
    const uint8_t bit = 1 << (pin - kExio);
    exio_out = high ? exio_out | bit : exio_out & ~bit;
    exio_dir &= ~bit;
    exio_set(0x01, exio_out);  // the level first, so the pin never drives the old one
    exio_set(0x03, exio_dir);
    return;
  }
  pinMode(pin, OUTPUT);
  digitalWrite(pin, high ? HIGH : LOW);
}

bool board_display_begin() {
  const bool expander = cfg.expander != ExpanderDriver::None;
  if (expander) Wire.begin(cfg.tp_sda, cfg.tp_scl, 400000);
  // Pins wired to something Outrigger doesn't use (a buzzer, a speaker
  // amplifier) that would make noise left floating or on (boards.json, hold_why).
  for (int16_t pin : cfg.hold_low) pin_write(pin, false);
  for (int16_t pin : cfg.hold_high) pin_write(pin, true);
  if (cfg.lcd_rst >= kExio) {  // Arduino_GFX resets the panel itself only from a GPIO
    pin_write(cfg.lcd_rst, true);
    delay(10);
    pin_write(cfg.lcd_rst, false);
    delay(10);
    pin_write(cfg.lcd_rst, true);
    delay(200);
  }
  bus = new ProfileSPI(gpio_or_none(cfg.lcd_dc), gpio_or_none(cfg.lcd_cs), gpio_or_none(cfg.lcd_sck),
                       gpio_or_none(cfg.lcd_mosi), gpio_or_none(cfg.lcd_miso), cfg.spi_mode);
  panel = make_panel();
  if (!panel->begin(cfg.spi_hz)) return false;
  // Some panels miss their first start after a cold power-on; their makers'
  // firmware restarts once, after the bus is up (boards.json, restart_why).
  if (cfg.restart_on_power_on && esp_reset_reason() == ESP_RST_POWERON) esp_restart();
  // The profile's colour order and mirrors, over Arduino_GFX's own MADCTL byte.
  if (panel_overrides(cfg.bgr, cfg.mirror_x, cfg.mirror_y)) {
    bus->beginWrite();
    bus->writeC8D8(0x36, panel_madctl(cfg.panel, cfg.rotation, cfg.bgr, cfg.mirror_x, cfg.mirror_y));
    bus->endWrite();
  }
  panel->fillScreen(0);
  pin_write(cfg.lcd_bl, true);

  if (cfg.tp_rst >= 0) {
    pin_write(cfg.tp_rst, false);
    delay(10);
    pin_write(cfg.tp_rst, true);
    // After its reset the touch chip ignores I2C for a while: FocalTech asks
    // for 300 ms; the CST816 answers after 50.
    delay(cfg.touch == TouchDriver::FT6336 ? 300 : 50);
  }
  if (!expander) Wire.begin(cfg.tp_sda, cfg.tp_scl, 400000);
  if (cfg.touch == TouchDriver::CST816) {
    // Keep the touch chip awake; asleep it ignores I2C until touched.
    Wire.beginTransmission(cfg.touch_address);
    Wire.write(0xFE);
    Wire.write(0x01);
    Wire.endTransmission();
  }
  return true;
}

void board_display_flush(int16_t x, int16_t y, int16_t w, int16_t h, const uint16_t *pixels) {
  panel->draw16bitRGBBitmap(x, y, const_cast<uint16_t *>(pixels), w, h);
}

#if UI_TOUCH_PROBE
int16_t board_touch_raw[2] = {-1, -1};
#endif

bool board_touch_read(int16_t *x, int16_t *y) {
  uint8_t buf[7];
  Wire.beginTransmission(cfg.touch_address);
  Wire.write(0x00);
  if (Wire.endTransmission(false) != 0) return false;
  if (Wire.requestFrom(cfg.touch_address, (uint8_t)sizeof buf) != sizeof buf) return false;
  for (uint8_t &b : buf) b = Wire.read();
  const uint8_t fingers = buf[2] & 0x0F;
  if (buf[2] == 0xFF || fingers == 0) return false;
  const int16_t rx = ((buf[3] & 0x0F) << 8) | buf[4], ry = ((buf[5] & 0x0F) << 8) | buf[6];
#if UI_TOUCH_PROBE
  board_touch_raw[0] = rx;
  board_touch_raw[1] = ry;
#endif
  touch_map::to_screen(rx, ry, cfg.rotation, native_w(), native_h(), x, y, cfg.touch_swap_xy, cfg.touch_invert_x,
                       cfg.touch_invert_y);
  return true;
}
